import mongoose from 'mongoose';
import { jsonOptions } from './shared/json.js';
import { searchable } from './shared/searchable.js';
import { lineItemSchema, totalsFields } from './shared/lineItem.js';
import { softDelete } from './shared/softDelete.js';

const { ObjectId } = mongoose.Schema.Types;

// A confirmed sale: usually created from an accepted quotation, whose lines
// and totals it copies as quoted, or entered directly.
const orderSchema = new mongoose.Schema(
  {
    // Generated by the server; never accepted from clients.
    orderNumber: { type: String, required: true, unique: true, immutable: true },
    // The quotation it was created from. Fixed once set.
    quotationId: { type: ObjectId, ref: 'Quotation', index: true, immutable: true },
    companyId: { type: ObjectId, ref: 'Company', required: true, index: true },
    contactId: { type: ObjectId, ref: 'Contact', index: true },
    items: [lineItemSchema],
    // Calculated by the server (services/quotationTotals.js), or copied from the quotation.
    ...totalsFields,
    orderDate: { type: Date, required: true },
    deliveryDate: { type: Date },
    statusId: { type: ObjectId, ref: 'OrderStatus', required: true, index: true },
    assignedTo: { type: ObjectId, ref: 'User', index: true },
    notes: { type: String, trim: true, maxlength: 5000 },
    createdBy: { type: ObjectId, ref: 'User' },
  },
  {
    timestamps: true,
    toJSON: jsonOptions({
      omit: ['deletedAt'],
      aliases: {
        quotationId: 'quotation',
        companyId: 'company',
        contactId: 'contact',
        statusId: 'status',
        assignedTo: 'assignedToUser',
        createdBy: 'createdByUser',
      },
    }),
  }
);

softDelete(orderSchema);

// Found by global search on these fields.
searchable(orderSchema, ['orderNumber']);

export default mongoose.model('Order', orderSchema);
